def get_row(lst, x):
    result = []
    for row_index, row in enumerate(lst):
        for col_index, value in enumerate(row):
            if value == x:
                result.append((row_index, col_index))
    result.sort(key=lambda item: item[0])
    for row_index in range(len(result)):
        for inner_index in range(row_index + 1, len(result)):
            if result[row_index][0] == result[inner_index][0]:
                if result[row_index][1] < result[inner_index][1]:
                    result[row_index], result[inner_index] = result[inner_index], result[row_index]
    return result 
